SELECT ?name ?point ?tsid WHERE {
  ?p rdfs:label ?name .
  FILTER(?name IN ("AHU01","CondPump02","HWPump01"))
  ?p ref:hasExternalReference/ ref:hasTimeseriesId ?tsid .
  BIND("x" AS ?point)
}

SELECT ?name ?tsid WHERE {
  ?uri ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
  FILTER(?uri IN (
    <http://buildgraph.org/BG_large_office_2004_0000#SupplyFan_AHU01_Electric_Power_Sensor>,
    <http://buildgraph.org/BG_large_office_2004_0000#CondPump02_Electric_Power_Sensor>,
    <http://buildgraph.org/BG_large_office_2004_0000#HWPump01_Electric_Power_Sensor>
  ))
  BIND("x" AS ?name)
}

SELECT ?uri ?tsid WHERE {
  ?uri ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
  FILTER(?uri IN (
    <http://buildgraph.org/BG_large_office_2004_0000#SupplyFan_AHU01_Electric_Power_Sensor>,
    <http://buildgraph.org/BG_large_office_2004_0000#CondPump02_Electric_Power_Sensor>,
    <http://buildgraph.org/BG_large_office_2004_0000#HWPump01_Electric_Power_Sensor>
  ))
}
